58	function buildFactualityResult(
59	  option: string,
60	  reason: string,
61	  grading: GradingConfig,
62	  resp: ProviderResponse,
63	): Omit<GradingResult, 'assertion'> {
64	  const scoreLookup = getFactualityScoreLookup(grading);
65	  const passing = Object.keys(scoreLookup).filter((key) => scoreLookup[key] > 0);
66	  const failing = Object.keys(scoreLookup).filter((key) => scoreLookup[key] === 0);
67	  const pass = passing.includes(option) && !failing.includes(option);
68	  const score = scoreLookup[option] ?? (pass ? 1 : 0);
69	
70	  return {
71	    pass,
72	    score,
73	    reason,
74	    tokensUsed: normalizeMatcherTokenUsage(resp.tokenUsage),
75	  };
