78	function parseFactualityJsonResponse(
79	  responseText: string,
80	): { option: string; reason: string } | undefined {
81	  try {
82	    const jsonData = extractFirstJsonObject<{ category?: string; reason?: string }>(responseText);
83	    if (!jsonData?.category || typeof jsonData.category !== 'string') {
84	      return undefined;
85	    }
86	
87	    const option = jsonData.category.trim().toUpperCase();
88	    if (!/^[A-E]$/.test(option)) {
89	      throw new Error(`Invalid category value: ${option}`);
90	    }
91	
92	    return {
93	      option,
94	      reason:
95	        jsonData.reason?.trim() ||
96	        `Category ${option}: ${FACTUALITY_CATEGORY_DESCRIPTIONS[option]}`,
97	    };
98	  } catch (err) {
99	    const error = err as Error;
100	    if (error.message.startsWith('Invalid category value:')) {
101	      throw error;
102	    }
103	    logger.debug(`JSON parsing failed: ${error.message}`);
104	    return undefined;
105	  }
106	}
