138	  label: string,
139	  resp: ProviderResponse,
140	): { parsed?: Partial<GradingResult>; failure?: Omit<GradingResult, 'assertion'> } {
141	  let jsonObjects: unknown[] = [];
142	  if (typeof resp.output === 'string') {
143	    try {
144	      jsonObjects = extractJsonObjects(resp.output);
145	      if (jsonObjects.length === 0) {
146	        return {
147	          failure: fail(`Could not extract JSON from ${label} response`, resp.tokenUsage),
148	        };
149	      }
150	    } catch (err) {
151	      return {
152	        failure: fail(
153	          `${label} produced malformed response: ${err}\n\n${resp.output}`,
154	          resp.tokenUsage,
155	        ),
156	      };
157	    }
158	  } else if (
159	    typeof resp.output === 'object' &&
160	    resp.output !== null &&
161	    !Array.isArray(resp.output)
162	  ) {
163	    jsonObjects = [resp.output];
164	  } else {
165	    return {
166	      failure: fail(
167	        `${label} produced malformed response - output must be string or object. Output: ${JSON.stringify(resp.output)}`,
168	        resp.tokenUsage,
169	      ),
170	    };
171	  }
172	
173	  const parsed = jsonObjects[0];
174	  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
175	    return {
176	      failure: fail(
177	        `${label} produced malformed response. We were not able to parse the response as JSON. Output: ${JSON.stringify(resp.output)}`,
178	        resp.tokenUsage,
179	      ),
180	    };
181	  }
182	
183	  return { parsed: parsed as Partial<GradingResult> };
