          failure: graderFail(`Could not extract JSON from ${label} response`, resp.tokenUsage),
        };
      }
    } catch (err) {
      return {
        failure: graderFail(
          `${label} produced malformed response: ${err}\n\n${resp.output}`,
          resp.tokenUsage,
